import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link, useParams } from 'react-router-dom';

import { Alert, Avatar, Button, Card, Flex, Typography } from 'antd';

import coinIcon from 'assets/images/coin.png';
import DeleteIcon from 'assets/images/icons/delete.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import CreateIcon from 'assets/images/icons/menu/create-channel.svg?react';
import SettingsIcon from 'assets/images/icons/menu/settings.svg?react';
